  /// saveAll method saves the sent List<MessageStore> as a bulk in one transaction
  /// Returns a <List<BoolResult>>
  static Future<List<dynamic>> saveAll(List<MessageStore> messagestores,
      {bool? exclusive, bool? noResult, bool? continueOnError}) async {
    List<dynamic>? result = [];
    // If there is no open transaction, start one
    final isStartedBatch = await RadioStore().batchStart();
    for (final obj in messagestores) {
      await obj.save(ignoreBatch: false);
    }
    if (!isStartedBatch) {
      result = await RadioStore().batchCommit(
          exclusive: exclusive,
          noResult: noResult,
          continueOnError: continueOnError);
      for (int i = 0; i < messagestores.length; i++) {
        if (messagestores[i].id == null) {
          messagestores[i].id = result![i] as int;
        }
      }
    }
    return result!;
  }

