  Future<int?> upsert({bool ignoreBatch = true}) async {
    try {
      final result = await _mnMessageStore.rawInsert(
          'INSERT OR REPLACE INTO messageStore (id, sender, recipient, messageText, messageId, sent, raw, timestamp)  VALUES (?,?,?,?,?,?,?,?)',
          [
            id,
            sender,
            recipient,
            messageText,
            messageId,
            sent,
            raw,
            timestamp != null ? timestamp!.millisecondsSinceEpoch : null
          ],
          ignoreBatch);
      if (result! > 0) {
        saveResult = BoolResult(
            success: true,
            successMessage: 'MessageStore id=$id updated successfully');
      } else {
        saveResult = BoolResult(
            success: false, errorMessage: 'MessageStore id=$id did not update');
